//! Polygon union under the NonZero fill rule.
//!
//! Re-implements Clipper2's `Union()` for integer paths using a vertical
//! decomposition ("slab partition"): the plane is split into vertical slabs
//! at every vertex x-coordinate and every edge-intersection x-coordinate,
//! and the union region inside each slab is a set of trapezoids, each
//! emitted as a quad. The returned paths therefore partition the union
//! region, so the sum of their signed areas equals the union area.

use crate::geom::{Path64, Paths64, Point64};

/// Tolerance used when comparing x-coordinates and interval heights.
const EPS: f64 = 1e-9;

/// A polygon edge carrying its owning subject's index.
#[derive(Clone, Copy)]
struct Edge {
    subject: usize,
    x1: f64,
    y1: f64,
    x2: f64,
    y2: f64,
}

impl Edge {
    /// Linear interpolation of y at x (valid when x lies within the x-range).
    fn y_at(&self, x: f64) -> f64 {
        let t = (x - self.x1) / (self.x2 - self.x1);
        self.y1 + t * (self.y2 - self.y1)
    }
}

/// An edge crossing of the vertical line x = xm within one slab.
struct Crossing {
    y: f64,
    subject: usize,
    dir: i32,
    edge: Edge,
}
