fn intersection_x(a: &Edge, b: &Edge) -> Option<f64> {
    let dax = a.x2 - a.x1; let day = a.y2 - a.y1;
    let dbx = b.x2 - b.x1; let dby = b.y2 - b.y1;
    let denom = dax * dby - day * dbx;
    if denom.abs() < EPS { return None; } // parallel or collinear
    let rx = b.x1 - a.x1; let ry = b.y1 - a.y1;
    let t = (rx * dby - ry * dbx) / denom;
    let u = (rx * day - ry * dax) / denom;
    if t < -EPS || t > 1.0 + EPS || u < -EPS || u > 1.0 + EPS { return None; }
    Some(a.x1 + t * dax)
}
