//! Re-implements Clipper2's `Union()` via vertical decomposition ("slab
//! partition"): the plane is split into vertical slabs at every vertex
//! x-coordinate and every edge-intersection x-coordinate. Inside a slab no
//! two edges cross, so the union region there is a stack of trapezoids,
//! each emitted as a CCW quad. The returned paths partition the union
//! region, hence the sum of their shoelace areas equals the union area,
//! which is all the caller observes.

use crate::geom::{Path64, Paths64, Point64};

/// Tolerance for x-coordinate dedup and degenerate-interval rejection.
const EPS: f64 = 1e-9;

/// A polygon edge tagged with its owning subject's index.
#[derive(Clone, Copy)]
struct Edge {
    subject: usize,
    x1: f64,
    y1: f64,
    x2: f64,
    y2: f64,
}

impl Edge {
    /// Linear interpolation of y at `x` (the edge must span `x`).
    fn y_at(&self, x: f64) -> f64 {
        let t = (x - self.x1) / (self.x2 - self.x1);
        self.y1 + t * (self.y2 - self.y1)
    }
}

/// A crossing of the vertical line `x = xm` by an edge within one slab.
struct Crossing {
    /// y-coordinate where the edge crosses `x = xm`.
    y: f64,
    /// Owning subject index.
    subject: usize,
    /// +1 if the edge runs left-to-right, -1 otherwise.
    dir: i32,
    /// The crossing edge (a straight line across the whole slab).
    edge: Edge,
}

/// X-coordinate of the intersection point of edges `a` and `b`, if the two
/// segments meet. Parallel and collinear pairs are skipped.
fn intersection_x(a: &Edge, b: &Edge) -> Option<f64> {
    let dax = a.x2 - a.x1;
    let day = a.y2 - a.y1;
    let dbx = b.x2 - b.x1;
    let dby = b.y2 - b.y1;
    let denom = dax * dby - day * dbx;
    if denom.abs() < EPS {
        return None; // parallel or collinear
    }
    let rx = b.x1 - a.x1;
    let ry = b.y1 - a.y1;
    let t = (rx * dby - ry * dbx) / denom;
    let u = (rx * day - ry * dax) / denom;
    if !(-EPS..=1.0 + EPS).contains(&t) || !(-EPS..=1.0 + EPS).contains(&u) {
        return None; // the lines meet outside at least one segment
    }
    Some(a.x1 + t * dax)
}

/// Union of `subjects` under the NonZero fill rule, re-implementing
/// Clipper2's `Union()`. Returns a partition of the union region into
/// trapezoid quads whose signed areas sum to the union area.
pub fn union(subjects: &Paths64) -> Paths64 {
    // Flatten every subject's edges, including each closing edge.
    let mut edges: Vec<Edge> = Vec::new();
    for (subject, path) in subjects.iter().enumerate() {
        let n = path.len();
        if n < 2 {
            continue;
        }
        for i in 0..n {
            let p = path[i];
            let q = path[(i + 1) % n];
            edges.push(Edge {
                subject,
                x1: p.x as f64,
                y1: p.y as f64,
                x2: q.x as f64,
                y2: q.y as f64,
            });
        }
    }

    // 1. Slab boundaries: every vertex x plus every edge-intersection x.
    let mut xs: Vec<f64> = Vec::new();
    for path in subjects {
        for p in path {
            xs.push(p.x as f64);
        }
    }
    for i in 0..edges.len() {
        for j in (i + 1)..edges.len() {
            if let Some(x) = intersection_x(&edges[i], &edges[j]) {
                xs.push(x);
            }
        }
    }
    xs.sort_by(|a, b| a.partial_cmp(b).unwrap());
    xs.dedup_by(|a, b| (*a - *b).abs() < EPS);

    let mut result: Paths64 = Vec::new();
    for slab in xs.windows(2) {
        let (x1, x2) = (slab[0], slab[1]);
        if x2 - x1 < EPS {
            continue; // zero-width slab
        }
        let xm = (x1 + x2) / 2.0;

        // 2. Crossings of x = xm with every edge strictly spanning xm.
        let mut crossings: Vec<Crossing> = Vec::new();
        for e in &edges {
            let (lo, hi) = if e.x1 < e.x2 {
                (e.x1, e.x2)
            } else {
                (e.x2, e.x1)
            };
            if lo < xm && xm < hi {
                crossings.push(Crossing {
                    y: e.y_at(xm),
                    subject: e.subject,
                    dir: if e.x2 > e.x1 { 1 } else { -1 },
                    edge: *e,
                });
            }
        }
        crossings.sort_by(|a, b| a.y.partial_cmp(&b.y).unwrap());

        // Sweep upward, keeping a per-subject winding counter. The interval
        // above a crossing is inside the union iff any counter is non-zero.
        let mut winding = vec![0i32; subjects.len()];
        for k in 0..crossings.len().saturating_sub(1) {
            winding[crossings[k].subject] += crossings[k].dir;
            if winding.iter().all(|&w| w == 0) {
                continue; // outside the union
            }
            let top_y = crossings[k + 1].y;
            if top_y - crossings[k].y < EPS {
                continue; // zero-height interval
            }
            // 3. Emit the trapezoid as a CCW quad (y-up): bottom edge from
            //    left to right, then the top edge from right to left.
            let bot = crossings[k].edge;
            let top = crossings[k + 1].edge;
            let quad: Path64 = vec![
                Point64::new(x1.round() as i64, bot.y_at(x1).round() as i64),
                Point64::new(x2.round() as i64, bot.y_at(x2).round() as i64),
                Point64::new(x2.round() as i64, top.y_at(x2).round() as i64),
                Point64::new(x1.round() as i64, top.y_at(x1).round() as i64),
            ];
            result.push(quad);
        }
    }
    result
}

