//! Stub geom for syntax/behavior checking only.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Point64 { pub x: i64, pub y: i64 }
impl Point64 { pub fn new(x: i64, y: i64) -> Self { Point64 { x, y } } }
pub type Path64 = Vec<Point64>;
pub type Paths64 = Vec<Path64>;
pub fn area(path: &Path64) -> f64 {
    let mut a = 0.0f64;
    for i in 0..path.len() {
        let p = path[i];
        let q = path[(i + 1) % path.len()];
        a += (p.x * q.y - q.x * p.y) as f64;
    }
    a / 2.0
}
pub fn translate_paths(paths: &Paths64, dx: i64, dy: i64) -> Paths64 {
    paths.iter().map(|p| p.iter().map(|pt| Point64::new(pt.x + dx, pt.y + dy)).collect()).collect()
}
pub fn winding_number(_path: &Path64, _px: f64, _py: f64) -> i32 { 0 }
