mod geom;
mod clipper;
use geom::{Point64, Path64, Paths64};
fn rect(x1: i64, y1: i64, x2: i64, y2: i64) -> Path64 {
    vec![Point64::new(x1,y1), Point64::new(x2,y1), Point64::new(x2,y2), Point64::new(x1,y2)]
}
fn total(subjects: &Paths64) -> f64 {
    clipper::union(subjects).iter().map(|p| geom::area(p)).sum()
}
fn main() {
    let subjects: Paths64 = vec![rect(0,0,50,50), rect(25,25,75,75), rect(50,50,100,100)];
    let t = total(&subjects);
    println!("total = {}", t);
    assert_eq!(t, 6250.0);
    // disjoint
    assert_eq!(total(&vec![rect(0,0,10,10), rect(20,20,30,30)]), 200.0);
    // full containment
    assert_eq!(total(&vec![rect(0,0,10,10), rect(2,2,8,8)]), 100.0);
    // identical polygons
    assert_eq!(total(&vec![rect(0,0,10,10), rect(0,0,10,10)]), 100.0);
    // triangle + triangle (diamond overlap), non-axis-aligned
    let t1: Path64 = vec![Point64::new(0,0), Point64::new(10,0), Point64::new(5,8)];
    let t2: Path64 = vec![Point64::new(0,4), Point64::new(10,4), Point64::new(5,12)];
    let a = total(&vec![t1.clone(), t2.clone()]);
    println!("tri union = {}", a);
    assert!((a - 70.0).abs() < 1e-6, "expected 70, got {}", a);
    println!("ALL OK");
}
EOF
